edits.new:
void gemm(int n, const float *A, const float *B, float *C) {
    if (n != 512) {
        fallback_gemm(n, A, B, C);
        return;
    }
    const void *parameters[22] = {0};
    parameters[4] = B;
    parameters[10] = A;
    parameters[16] = C;

    float *at = malloc((size_t)512 * 512 * sizeof(float));
    if (!at) {
        sera_libxsmm_512(parameters);
        return;
    }

    /* Physical at[k*512+i]=A[i*512+k]. The supplied TRANS_B beta-zero
       primitive computes C^T=B^T*A^T with all leading dimensions 512. */
    sme_transpose(512, A, at);
    parameters[10] = at;
    sera_libxsmm_tb(parameters);
    free(at);
}
